class Solution {
    public int numRabbits(int[] answers){
        Map<Integer,Integer> frequency=new HashMap<>();
        for(int answer:answers)frequency.merge(answer,1,Integer::sum);
        int result=0;
        for(Map.Entry<Integer,Integer> entry:frequency.entrySet()){
            int size=entry.getKey()+1,count=entry.getValue();
            result+=(count+size-1)/size*size;
        }
        return result;
    }
}

code.kotlin:
class Solution {
    fun numRabbits(answers:IntArray):Int{
        val frequency=answers.toList().groupingBy{
            it
        }.eachCount();
        var result=0;
        for((answer,count)in frequency){
            val size=answer+1;
            result+=(count+size-1)/size*size
        };
        return result
    }
}

code.cpp:
class Solution {
    public: int numRabbits(vector<int>& answers){
        unordered_map<int,int> frequency;
        for(int answer:answers)++frequency[answer];
        int result=0;
        for(auto [answer,count]:frequency){
            int size=answer+1;
            result+=(count+size-1)/size*size;
        }
        return result;
    }
};
